 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            if len(cells) < 8:
                continue
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            # This task's outlined container has a single opening in its top edge.
            holes = [x for x in range(left, right + 1) if grid[top][x] != 5]
            if top == 0 or len(holes) != 1:
                continue
            opening = holes[0]
            for y in range(top, bottom + 1):
                for x in range(left, right + 1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            left_lip = sum(grid[top][x] == 5 for x in range(left, opening))
            right_lip = sum(grid[top][x] == 5 for x in range(opening + 1, right + 1))
            direction = -1 if left_lip >= right_lip else 1
            x = opening
            while 0 <= x < w:
                if grid[top - 1][x] == 0:
                    out[top - 1][x] = 2
                x += direction
    return out
